SELECT 
FROM wallets
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1
FOR UPDATE

SELECT
    COALESCE(SUM(CASE WHEN type IN ('income', 'transfer_in') AND status = 'success' THEN amount ELSE 0 END), 0) AS income,
    COALESCE(SUM(CASE WHEN type = 'transfer_out' AND status = 'success' THEN amount + COALESCE(fee_amount, 0)
                      WHEN type = 'expense' AND status = 'success' THEN amount
                      ELSE 0 END), 0) AS spent
FROM transactions
WHERE wallet_id = #{walletId}
  AND user_id = #{userId}
  AND occurred_at >= #{start}
  AND occurred_at < #{end}

